import {THREE,canvasTexture} from './kit.js';
const cells={skin:[0,0,.5,.5],shirt:[.5,0,.5,.5],shorts:[0,.5,.25,.25],socks:[.25,.5,.25,.25],bootL:[.5,.5,.25,.25],bootR:[.5,.5,.25,.25],eyes:[.75,.5,.25,.25],eyebrows:[0,.75,.25,.25],short02:[.25,.75,.5,.25],crop:[.25,.75,.5,.25]};
export function atlasGeometry(geometries,hair){
 const parts=Object.entries(geometries).filter(([name])=>!['short02','crop'].includes(name)||name===hair),total=parts.reduce((sum,[,g])=>sum+g.attributes.position.count,0),result=new THREE.BufferGeometry(),ranges={};
 for(const[name,size]of Object.entries({position:3,normal:3,uv:2,skinIndex:4,skinWeight:4})){const out=name==='skinIndex'?new Uint16Array(total*size):new Float32Array(total*size);let offset=0;for(const[part,g]of parts){const source=g.attributes[name];for(let i=0;i<source.count;i++)for(let j=0;j<size;j++){let value=source.array[i*size+j];if(name==='uv'){if(part==='socks'||part==='shorts')value=((value%1)+1)%1;const cell=cells[part];value=j===0?cell[0]+.002+value*(cell[2]-.004):1-cell[1]-cell[3]+.002+value*(cell[3]-.004);}out[(offset+i)*size+j]=value;}offset+=source.count;}result.setAttribute(name,new THREE.BufferAttribute(out,size));}
 const indices=[];let offset=0;for(const[part,g]of parts){ranges[part]={start:offset,count:g.attributes.position.count};for(const i of g.index.array)indices.push(i+offset);offset+=g.attributes.position.count;}result.setIndex(indices);result.computeBoundingSphere();result.userData.parts=ranges;return result;
}
function kitColors(d){const official=d.team==='official',staff=['coach','assistant','doctor','physio'].includes(d.role),away=d.team==='away';return{shirt:official?'#77cbd1':staff?'#27343c':d.keeper?(away?'#9584b2':'#176f62'):away?'#ebcc3d':'#bb1d32',shorts:official||staff||away?'#222c31':d.keeper?'#176f62':'#ab182c',ink:away&&!d.keeper?'#222c31':'#f4f1e8',socks:official||staff?'#27343c':'#dfdfd6'};}
export function characterAtlas(d,textures,jerseyTexture,size=1024){
 const colors=kitColors(d),jersey=jerseyTexture(d,d.team==='away'?textures.awayCrest:textures.crest,colors);
 const texture=canvasTexture(size,size,c=>{c.scale(size,size);for(const[name,cell]of Object.entries(cells)){if(name==='bootR'||name==='crop'||name==='short02')continue;c.save();c.beginPath();c.rect(...cell);c.clip();c.fillStyle=name==='skin'?'#b29275':colors[name]||'#eee';c.fillRect(...cell);const image=name==='skin'?(d.dark?textures.dark:textures.light).image:name==='shirt'?jersey.image:name==='eyes'?textures.eyes.image:name==='eyebrows'?textures.brows.image:name==='bootL'?textures.boot.image:null;if(image)c.drawImage(image,...cell);if(name==='bootL'){c.globalCompositeOperation='multiply';c.fillStyle=new THREE.Color(d.boot||0xcac6bd).getStyle();c.fillRect(...cell);}c.restore();}
  const cell=cells.short02;c.save();c.beginPath();c.rect(...cell);c.clip();c.clearRect(...cell);if(d.hair==='crop'){c.fillStyle='#27231e';c.fillRect(...cell);}else{c.drawImage(textures.short02.image,...cell);c.globalCompositeOperation='multiply';c.fillStyle=new THREE.Color(d.hairColor||0x9a8476).getStyle();c.fillRect(...cell);c.globalCompositeOperation='destination-in';c.drawImage(textures.short02.image,...cell);}c.restore();
 });jersey.dispose();return texture;
}
export function drawJersey(d,crest,colors){return canvasTexture(1024,1024,c=>{
 c.fillStyle=colors.shirt;c.fillRect(0,0,1024,1024);c.strokeStyle='rgba(20,0,0,.055)';c.lineWidth=2;for(let y=0;y<1024;y+=36){c.beginPath();c.moveTo(0,y);c.lineTo(1024,y);c.stroke();}c.fillStyle='rgba(255,255,255,.03)';for(let y=0;y<1024;y+=5)c.fillRect(0,y,1024,1);
 const player=d.player,club=d.team==='away'?'BORUSSIA DORTMUND':d.team==='official'?'MATCH OFFICIAL':d.role==='player'||d.role==='substitute'?'FC BAYERN MÜNCHEN':'FC BAYERN · STAFF';c.fillStyle=colors.ink;c.textAlign='center';c.font='bold 43px Arial';c.fillText(club,768,214,292);
 if(player.number){c.font='bold 475px Arial';c.fillText(String(player.number),768,640,player.number<10?120:190);}else{c.font='bold 96px Arial';c.fillText(player.name,768,510,285);}
 c.font='bold 52px Arial';c.fillText(player.name,768,755,290);if(crest&&d.team!=='official')c.drawImage(crest,327,240,53,102);
 if(d.team==='official'){c.fillStyle='#18292d';c.fillRect(192,350,128,24);c.fillRect(315,350,92,9);c.font='bold 30px Arial';c.fillText('REFEREE',256,530);}else if(['doctor','physio'].includes(d.role)){c.font='bold 57px Arial';c.fillText('MEDICAL',256,520);}else{c.font='bold 130px Arial';c.fillText(d.team==='away'?'DORTMUND':'T',256,535,d.team==='away'?230:75);}
 c.strokeStyle='rgba(255,255,245,.5)';c.lineWidth=3;for(const offset of[0,512])for(const x of[49,463]){c.beginPath();c.moveTo(offset+x,190);c.lineTo(offset+x,315);c.stroke();}
 });}
